'use server'

import { revalidateTag } from 'next/cache'

export async function createPost(formData: FormData) {
  // In a real application, you would validate and save the post data to a database here.
  // For this example, we'll simulate a database operation.
  const title = formData.get('title')
  const content = formData.get('content')

  console.log('Creating post:', { title, content })

  // Simulate database delay
  await new Promise(resolve => setTimeout(resolve, 500))

  // Invalidate the cache for the 'posts' tag.
  // This ensures that any data fetched with the 'posts' tag is re-fetched on the next request.
  // The user will see fresh data immediately after the action completes.
  revalidateTag('posts')
}

