export async function createPost(formData: FormData) {
  // 1. Validate form data
  const title = formData.get('title')
  const content = formData.get('content')

  if (!title || !content) {
    throw new Error('Title and content are required')
  }

  // 2. Perform database mutation
  // In a real app, you would save to your database here.
  console.log('Creating post:', { title, content })

  // Simulate database delay
  await new Promise(resolve => setTimeout(resolve, 500))

  // 3. Invalidate cache
  // This purges the cache for the 'posts' tag.
  // The next request for data tagged with 'posts' will be a cache MISS and fetch fresh data.
  // This also invalidates the client-side Router Cache for routes using this data.
  revalidateTag('posts')
}

